<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id']))redirect('index.php');require_once dirname(__DIR__).'/private/finance_recurrences.php';require_once dirname(__DIR__).'/private/ui.php';
$id=max(0,(int)($_GET['id']??0));$s=[];$list=[];$sources=[];$properties=[];$proposal=null;$history=[];
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{$action=(string)($_POST['action']??'');if($action==='save'){$id=financeRecurringSave($pdo,(int)$_SESSION['admin_id'],$_POST,$id);$_SESSION['app_notice']='Finanzvorlage gespeichert. Noch keine Rechnung ausgestellt oder Ausgabe gebucht.';}elseif($action==='preview'){$token=financeRecurringPreview($pdo,(int)$_SESSION['admin_id'],$id,(string)($_POST['through']??''));redirect('finance_recurrences.php?id='.$id.'&proposal='.$token);}elseif($action==='apply'){if(empty($_POST['confirm']))throw new RuntimeException('Vorschau ausdrücklich bestätigen.');$created=financeRecurringApply($pdo,(int)$_SESSION['admin_id'],(string)($_POST['token']??''));$_SESSION['app_notice']=count($created).' Entwürfe/Prüfaufgaben angelegt. Keine Ausstellung, Buchung oder E-Mail.';}else throw new RuntimeException('Aktion unbekannt.');}catch(Throwable $e){gszUiError($e);}redirect('finance_recurrences.php'.($id?'?id='.$id:''));}
try{$list=$pdo->query('SELECT * FROM finance_recurrences ORDER BY active DESC,next_due_date,id LIMIT 200')->fetchAll();if($id){$q=$pdo->prepare('SELECT * FROM finance_recurrences WHERE id=?');$q->execute([$id]);$s=$q->fetch()?:throw new RuntimeException('Vorlage fehlt.');$q=$pdo->prepare('SELECT * FROM finance_recurrence_occurrences WHERE recurrence_id=? ORDER BY scheduled_for DESC LIMIT 100');$q->execute([$id]);$history=$q->fetchAll();}$q=$pdo->prepare("SELECT id,number,recipient_name FROM invoices WHERE document_kind='invoice' AND (status IN ('issued','paid') OR id=?) ORDER BY (id=?) DESC,id DESC LIMIT 200");$q->execute([$s['source_invoice_id']??0,$s['source_invoice_id']??0]);$sources=$q->fetchAll();$properties=$pdo->query('SELECT id,name FROM properties ORDER BY name LIMIT 2000')->fetchAll();if(isset($_GET['proposal'])){$q=$pdo->prepare('SELECT * FROM finance_recurrence_proposals WHERE token=? AND recurrence_id=? AND admin_id=?');$q->execute([(string)$_GET['proposal'],$id,$_SESSION['admin_id']]);$proposal=$q->fetch();}}catch(Throwable $e){gszUiError($e);}gszPageStart('Wiederkehrende Rechnungen und Ausgabenprüfung');
?><p>Rechnungen werden ausschließlich als prüfbare Entwürfe aus einer gespeicherten Originalrechnung kopiert. Empfänger, Preise, Leistung und Steuer prüfen; keine automatische Nummer oder Ausstellung. Ausgaben erzeugen nur Prüfaufgaben: Ein erwarteter Betrag ist keine tatsächliche Ausgabe und ersetzt keinen neuen Originalbeleg.</p><p><a href="finance_recurrences.php?new=1">Neue Finanzvorlage</a> · <a href="accounting.php">Belegprüfung</a></p><section class="card"><?php foreach($list as $item):?><p><a href="?id=<?=(int)$item['id']?>"><?=e($item['title'])?></a> · <?=e($item['next_due_date'])?> · <?=$item['active']?'Aktiv':'Pausiert'?></p><?php endforeach?></section>
<?php if($s||isset($_GET['new'])):?><section class="card"><form method="post"><?php gszFields('save');?><input type="hidden" name="row_version" value="<?=(int)($s['row_version']??0)?>"><label>Bezeichnung<input name="title" maxlength="190" value="<?=e($s['title']??'')?>" required></label><label>Art<select name="kind"><option value="invoice">Rechnungsentwurf</option><option value="expense_review" <?=($s['kind']??'')==='expense_review'?'selected':''?>>Ausgabe prüfen (keine Buchung)</option></select></label><label>Originalrechnung (nur Rechnungsentwürfe)<select name="source_invoice_id"><option value="0">Keine / Ausgabe prüfen</option><?php foreach($sources as $source):?><option value="<?=(int)$source['id']?>" <?=(int)($s['source_invoice_id']??0)===(int)$source['id']?'selected':''?>><?=e($source['number'].' · '.$source['recipient_name'])?></option><?php endforeach?></select></label><label>Objekt (optional)<select name="property_id"><option value="0">Ohne / ursprüngliches Rechnungsobjekt</option><?php foreach($properties as $p):?><option value="<?=(int)$p['id']?>" <?=(int)($s['property_id']??0)===(int)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach?></select></label><label>Intervall<select name="frequency"><?php foreach(['weekly'=>'Wöchentlich','biweekly'=>'Alle zwei Wochen','monthly'=>'Monatlich','quarterly'=>'Vierteljährlich','yearly'=>'Jährlich'] as $value=>$label):?><option value="<?=$value?>" <?=($s['frequency']??'monthly')===$value?'selected':''?>><?=e($label)?></option><?php endforeach?></select></label><label>Nächste Fälligkeit<input name="next_due_date" type="date" required value="<?=e($s['next_due_date']??date('Y-m-d'))?>"></label><label>Monatsanker (1–31, kurzer Monat: letzter Tag)<input name="anchor_day" type="number" min="1" max="31" value="<?=(int)($s['anchor_day']??date('j'))?>" required></label><label>Zahlungsziel für neuen Entwurf (Tage nach Leistung)<input name="due_days" type="number" min="0" max="365" value="<?=(int)($s['due_days']??14)?>"></label><label>Erwarteter Ausgabenbetrag EUR (optional, kein Istwert)<input name="expected_amount" inputmode="decimal" value="<?=isset($s['expected_cents'])?e(number_format((int)$s['expected_cents']/100,2,',','')):''?>"></label><label>Hinweise<textarea name="notes" maxlength="5000"><?=e($s['notes']??'')?></textarea></label><label><input type="checkbox" name="active" value="1" <?=!isset($s['active'])||$s['active']?'checked':''?>> Aktiv (Vorschau weiterhin erforderlich)</label><button>Finanzvorlage speichern</button></form></section><?php endif?>
<?php if($s):?><section class="card"><form method="post"><?php gszFields('preview');?><label>Vorschau bis (höchstens24 Fälligkeiten, maximal ein Jahr)<input name="through" type="date" required value="<?=e($s['next_due_date'])?>"></label><button>Fälligkeiten als Vorschau prüfen</button></form><?php if($proposal):$plan=json_decode($proposal['payload'],true);?><h2>Vorschau – keine Entwürfe/Prüfaufgaben angelegt</h2><?php foreach($plan['rows'] as $row):?><p><?=e($row['scheduled_for'])?> · <?=$row['existing']?'Bereits vorhanden, bleibt erhalten':($s['kind']==='invoice'?'Neuer Rechnungsentwurf':'Neue Ausgaben-Prüfaufgabe')?></p><?php endforeach?><form method="post"><?php gszFields('apply');?><input type="hidden" name="token" value="<?=e($proposal['token'])?>"><label><input name="confirm" type="checkbox" required> Vorschläge geprüft; ausschließlich Entwürfe/Prüfaufgaben erstellen.</label><button>Finanzvorschau bestätigen</button></form><?php endif?><h2>Bisherige Fälligkeiten</h2><?php foreach($history as $o):?><p><?=e($o['scheduled_for'])?> · <?php if($o['invoice_id']):?><a href="invoice.php?id=<?=(int)$o['invoice_id']?>">Rechnungsentwurf / Dokument</a><?php else:?><a href="task.php?id=<?=(int)$o['task_id']?>">Ausgaben-Prüfaufgabe</a><?php endif?></p><?php endforeach?></section><?php endif?><?php gszPageEnd();?>
